<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import { route as routeSource,go,setQuery } from '../workbench/navigation';
import { learningSpaces } from '../workbench/learning-space-mock';
import { executionNames,reviewNames } from '../workbench/activity-review-mock';
import { overviewData,overviewTrend,overviewGroups,type OverviewAttention } from '../workbench/runtime-overview';
import type { ObservationSection } from '../workbench/runtime-observation';
const route=routeSource,location=window.location;
const scope=computed(()=>learningSpaces.find(s=>s.id===route.scope));
const range=computed(()=>route.range||'all');
const invalid=computed(()=>route.scope&&!scope.value?'所选学习空间不存在，未扩大为全部学生。':!['all','today','7days','30days','custom'].includes(range.value)?'所选时间范围不存在。':range.value==='custom'&&((route.since&&!/^\d{4}-\d{2}-\d{2}$/.test(route.since))||(route.until&&!/^\d{4}-\d{2}-\d{2}$/.test(route.until)))?'请输入有效的日期。':range.value==='custom'&&route.since&&route.until&&route.since>route.until?'开始日期不能晚于结束日期。':'');
const data=computed(()=>overviewData(route.scope,range.value,route.since,route.until));
const group=computed(()=>overviewGroups.find(g=>g.id===route.tab)||overviewGroups[1]);
const attention=computed(()=>data.value.attention.filter(r=>r.group===group.value.id));
const attentionPage=ref(1),trendMetric=ref<'activities'|'rounds'>('activities');
watch(()=>[route.tab,route.scope,route.range,route.since,route.until,attention.value.length],()=>{attentionPage.value=1;});
const trend=computed(()=>overviewTrend(data.value.activities,range.value,route.since,route.until));
const trendMax=computed(()=>Math.max(1,...trend.value.days.map(d=>d[trendMetric.value])));
const queries=()=>({scope:route.scope,range:range.value,since:route.since,until:route.until,returnTo:location.hash});
function activityList(extra:Record<string,string>={}){go('trace-list',{filter:route.scope,range:range.value,since:route.since,until:route.until,...extra,returnTo:location.hash});}
function observation(tab:ObservationSection,extra:Record<string,string>={}){go('objects',{...queries(),tab,...extra});}
function openAttention(row:OverviewAttention){go(row.page,{...queries(),...row.values});}
function openActivity(id:string){go('activity',{id,returnTo:location.hash});}
function scopeName(ids:string[]){return ids.map(id=>{const s=learningSpaces.find(s=>s.id===id);return s?s.studentName+' · '+s.name:id;}).join('；')||'共享定义';}
function dayActivities(day:string){go('trace-list',{filter:route.scope,range:'custom',since:day,until:day,returnTo:location.hash});}
const moduleNotes=computed(()=>({
  Domain:'当前依赖待补 '+data.value.modules[0]!.data.records.filter(r=>r.kind==='依赖引用').length+' 项；引用不等于掌握。',
  Learning:'当前条件待核对 '+data.value.modules[1]!.data.records.filter(r=>r.kind==='定义条件').length+' 项；按空间与 Claim 计。',
  Evaluation:'当前学习要求：'+data.value.goals.map(g=>g.name+' '+g.count).join(' / ')+'。不随日期回退。',
  Interaction:'记录决策与实际行动；当前在线、等待与活动是否仍在进行尚未记录。',
  Reasoning:'期间结果提交 '+data.value.modules[4]!.period.filter(r=>r.kind==='结果提交').length+' 次；候选拒绝不等于整轮失败。',
  Evolution:'当前采用差异 '+data.value.modules[5]!.data.changed.length+' 项；不同不等于必须更新。',
}));
function moduleMetrics(id:ObservationSection){const m=data.value.modules.find(m=>m.id===id)!;return id==='Interaction'?m.metrics.slice(1,3):m.metrics.slice(0,2);}
function reset(){setQuery({scope:'',range:'all',since:'',until:'',tab:'review'});}
</script>
<template><div class="wb-page runtime-overview">
  <header class="page-header"><div><h2>运行总览</h2><p class="page-desc">查看学习活动的处理情况、各模块变化及需要核对的事项。</p></div><span class="badge">Mock · 共用当前课程记录</span></header>
  <div class="overview-filters"><label>运行范围<select aria-label="运行范围" :value="route.scope" @change="setQuery({scope:($event.target as HTMLSelectElement).value})"><option value="">全部学习空间</option><option v-if="route.scope&&!scope" :value="route.scope">{{route.scope}} · 不存在</option><option v-for="s in learningSpaces" :key="s.id" :value="s.id">{{s.studentName}} · {{s.name}} · {{s.id}}</option></select></label><label>统计时间<select aria-label="统计时间" :value="range" @change="setQuery({range:($event.target as HTMLSelectElement).value})"><option value="all">全部记录</option><option value="today">今天</option><option value="7days">近 7 天</option><option value="30days">近 30 天</option><option value="custom">自定义日期</option></select></label><template v-if="range==='custom'"><label>开始日期<input type="date" :value="route.since" @input="setQuery({since:($event.target as HTMLInputElement).value})"/></label><label>结束日期<input type="date" :value="route.until" @input="setQuery({until:($event.target as HTMLInputElement).value})"/></label></template><button class="btn" @click="reset">重置筛选</button></div>
  <p v-if="invalid" class="callout danger" role="alert">{{invalid}}</p>
  <template v-else>
    <p class="overview-note">活动按开始日期筛选；标为“当前”的内容、条件和评价状态不随日期回退。<a href="#overview-methods" @click.prevent="($refs.methods as HTMLDetailsElement).open=true;($refs.methods as HTMLDetailsElement).scrollIntoView({block:'nearest'})">统计口径</a></p>
    <section class="metric-grid overview-metrics" aria-label="期间运行指标">
      <button class="metric-card" @click="activityList()"><span>学习活动</span><strong>{{data.activities.length}}</strong><small>{{data.students}} 名学生 · {{data.spaces}} 个学习空间 →</small></button>
      <button class="metric-card" @click="activityList()"><span>处理轮次</span><strong>{{data.rounds.length}}</strong><small>所选活动内已记录轮次 →</small></button>
      <button class="metric-card" @click="observation('Reasoning',{filter:'模型调用'})"><span>模型调用（示例）</span><strong>{{data.calls}}</strong><small>包含重试；非真实调用 →</small></button>
      <button class="metric-card" @click="activityList({review:'question'})"><span>审查有疑点</span><strong>{{data.attention.filter(r=>r.group==='review').length}}</strong><small>所选活动当前的人工标记 →</small></button>
    </section>
    <div class="overview-top">
      <section class="panel trend-panel"><div class="overview-heading"><h3>学习活动趋势</h3><div class="trend-toggle"><button :aria-pressed="trendMetric==='activities'" @click="trendMetric='activities'">活动数</button><button :aria-pressed="trendMetric==='rounds'" @click="trendMetric='rounds'">轮次数</button></div></div><p class="muted">按活动开始日汇总 · 单位：{{trendMetric==='activities'?'项活动':'轮'}}{{trend.clipped?' · 图中仅展示所选期间末 14 天，顶部统计仍覆盖整个期间':''}}</p>
        <div v-if="data.activities.length" class="daily-chart" :style="{'--days':trend.days.length}" role="group" aria-label="每日运行量"><button v-for="d in trend.days" :key="d.day" class="day-bar" :aria-label="d.day+'：'+d[trendMetric]+(trendMetric==='activities'?' 项活动':' 轮')+'，查看当天活动'" @click="dayActivities(d.day)"><span class="bar-value">{{d[trendMetric]}}</span><span class="bar-track"><i :style="{height:(d[trendMetric]/trendMax*100)+'%'}"></i></span><span class="bar-date">{{d.day.slice(5)}}</span></button></div><p v-else class="empty chart-empty">所选期间没有已记录的学习活动。</p>
        <p class="muted">无记录的日期记为 0；不代表学生没有学习。真实耗时、成本和准确率尚未接入。</p>
      </section>
      <section class="panel processing-panel"><h3>执行与评价</h3><p class="muted">所选活动的处理结果</p><div class="execution-grid"><button v-for="s in data.executions" :key="s.id" :class="{failure:s.id==='failed'&&s.value}" @click="activityList({status:s.id})"><span>{{s.name}}</span><strong>{{s.value}}</strong></button></div><p v-if="data.unrecorded" class="muted">{{data.unrecorded}} 项活动未记录处理状态。</p><p class="muted">处理完成不等于学习结束或目标达标；当前在线与等待情况未记录。</p>
        <div class="evaluation-counts" aria-label="期间评价产物"><button @click="observation('Evaluation',{filter:'Evidence'})">Evidence <strong>{{data.evidence}}</strong></button><button @click="observation('Evaluation',{filter:'Belief 更新'})">Belief 更新 <strong>{{data.beliefs}}</strong></button><button @click="observation('Evaluation',{filter:'目标评价'})">目标评价 <strong>{{data.assessments}}</strong></button></div><p class="muted">更新按每轮 Claim 记录计数；产物条数不等于独立样本数或达标项数。</p>
      </section>
    </div>
    <section class="panel overview-attention"><div class="overview-heading"><h3>需要关注</h3><button class="text-link" @click="observation('Reasoning',{filter:'语义校验',review:'attention'})">另看候选拒绝记录 {{data.rejected}} →</button></div><div class="attention-tabs" role="tablist" aria-label="关注类型"><button v-for="g in overviewGroups" :key="g.id" role="tab" :aria-selected="group.id===g.id" :class="{active:group.id===g.id}" @click="setQuery({tab:g.id})">{{g.name}} <span>{{data.attention.filter(r=>r.group===g.id).length}}</span></button></div><p class="muted">{{group.note}}</p>
      <div v-for="r in attention.slice((attentionPage-1)*5,attentionPage*5)" :key="r.id" class="overview-attention-row"><div><button class="text-link attention-name" @click="openAttention(r)">{{r.title}}</button><p>{{r.summary}}</p><small>{{scopeName(r.scopeIds)}} · {{r.time}}</small></div><span class="badge" :class="r.group==='execution'?'red':'amber'">{{r.status}}</span><button class="text-link" :aria-label="'追溯 '+r.id" @click="openAttention(r)">查看依据 →</button></div><p v-if="!attention.length" class="empty">当前范围暂无已记录的{{group.name}}。这不等于已经证明没有问题。</p>
      <div v-if="attention.length>5" class="attention-paging"><button class="btn" :disabled="attentionPage===1" @click="attentionPage--">上一页</button><span>{{attentionPage}} / {{Math.ceil(attention.length/5)}}</span><button class="btn" :disabled="attentionPage*5>=attention.length" @click="attentionPage++">下一页</button></div>
    </section>
    <section class="table-card overview-modules"><div class="overview-heading"><h3>各空间与运行模块</h3><span class="muted">运行摘要 · 详情进入空间观测</span></div><table class="data-table"><thead><tr><th>模块</th><th>记录摘要</th><th>当前情况与边界</th><th></th></tr></thead><tbody><tr v-for="m in data.modules" :key="m.id"><td><strong>{{m.name}}</strong><small>{{m.title}}</small></td><td><span v-for="metric in moduleMetrics(m.id)" :key="metric.label" class="module-metric">{{metric.label}} <b>{{metric.value}}</b><small>{{metric.note}}</small></span></td><td>{{moduleNotes[m.id]}}</td><td><button class="text-link" :aria-label="'观测 '+m.name" @click="observation(m.id)">查看观测 →</button></td></tr></tbody></table></section>
    <section class="table-card overview-activities"><div class="overview-heading"><h3>最近学习活动</h3><button class="text-link" @click="activityList()">查看全部 {{data.activities.length}} 项 →</button></div><table class="data-table"><thead><tr><th>活动 / 开始时间</th><th>学生 / 学习空间</th><th>执行状态</th><th>审查情况</th><th>评价产物</th></tr></thead><tbody><tr v-for="r in data.activities.slice(0,5)" :key="r.activity.id"><td><button class="text-link" @click="openActivity(r.activity.id)">{{r.activity.name}}</button><small>{{r.activity.at}} · {{r.audit?.rounds.length||0}} 轮</small></td><td>{{r.space.studentName}}<small>{{r.space.name}}</small></td><td><span class="badge">{{r.audit?executionNames[r.audit.execution]:'未记录'}}</span></td><td><span class="badge" :class="{amber:r.audit?.review==='question'}">{{r.audit?reviewNames[r.audit.review]:'未复核'}}</span></td><td>{{r.activity.evidence.length}} 条 Evidence<small>{{r.audit?.rounds.some(t=>t.changes.length)?'含分方面判断':'未记录 Belief 更新'}}</small></td></tr></tbody></table><p v-if="!data.activities.length" class="empty">此范围没有学习活动记录，不借用其他空间的记录。</p></section>
    <details id="overview-methods" ref="methods" class="overview-methods"><summary>统计口径与数据边界</summary><ul><li>活动、处理轮次和审查疑点按活动开始日期筛选，使用本机自然日；审查状态展示这些活动当前的人工标记，不按复核日期另选活动。</li><li>模块中的“期间”使用记录时间。当前示例的调用、轮次和评价沿用活动日期，定义修改采用修改记录日期；“当前”表示最新快照，不是历史状态回放。</li><li>学习活动、处理轮次、模型调用、Evidence、Belief 更新和学习要求各自计数，不能相加为一个成功率。个人能力状态保持学习空间隔离，不汇总为平均掌握度。</li><li>内容准备按空间与章节计数，配置条件按空间与 Claim 计数，采用差异按空间与定义计数；同一引用问题不在多个模块重复列入关注清单。</li><li>各模块共用当前领域、教材、目标、Claim、学习空间及交互审查 mock 数据。没有真实调用、性能测量或自动诊断；未知不显示成零，候选通过与结果提交也不保证语义正确。</li></ul></details>
    <div class="overview-shortcuts"><span class="muted">管理入口</span><button class="text-link" @click="go('textbooks')">准备一个章节</button><button class="text-link" @click="go('domain')">管理领域模型</button><button class="text-link" @click="observation('Evolution')">查看定义变更与采用差异 →</button></div>
  </template>
</div></template>
<style scoped>
.runtime-overview{max-width:1440px}.overview-filters{display:flex;gap:14px;align-items:end;flex-wrap:wrap}.overview-filters label{margin:0;min-width:150px}.overview-filters label:first-child{min-width:285px}.overview-note{font-size:12px;color:#78867e;margin:12px 0 18px}.overview-note a{margin-left:10px;color:#2d6a4f}.overview-metrics .metric-card{padding:15px 18px}.overview-metrics .metric-card>span{font-size:13px}.overview-top{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:18px}.overview-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.overview-heading h3{margin:0}.trend-toggle{display:flex;border:1px solid #dae4de;border-radius:5px;overflow:hidden;flex-shrink:0}.trend-toggle button{border:0;background:#fff;padding:4px 10px;font-size:12px;color:#6b7f73}.trend-toggle button[aria-pressed=true]{background:#eaf4ed;color:#2d6a4f}.daily-chart{display:grid;grid-template-columns:repeat(var(--days),minmax(0,1fr));gap:7px;height:172px;align-items:end;margin:12px 0 14px}.day-bar{display:flex;flex-direction:column;align-items:center;border:0;background:none;padding:0;min-width:0;height:100%;font-size:11px;color:#698172}.bar-value{line-height:20px;color:#365d45}.bar-track{height:125px;display:flex;align-items:end;width:70%;max-width:40px;border-bottom:1px solid #cfddd4}.bar-track i{width:100%;background:#619c7d;border-radius:3px 3px 0 0;min-height:0}.bar-date{margin-top:7px;font-size:10px;white-space:nowrap}.chart-empty{min-height:172px;display:flex;align-items:center;justify-content:center}.execution-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:10px 0}.execution-grid button{border:1px solid #e4ebe6;background:#f9fbfa;border-radius:5px;padding:8px 4px;display:flex;flex-direction:column;gap:5px;color:#5a7162;font-size:12px}.execution-grid strong{font-size:20px;color:#304f3b}.execution-grid .failure{background:#fdf0ed}.evaluation-counts{display:flex;gap:12px;border-top:1px solid #e5ece7;padding-top:12px;margin-top:12px;flex-wrap:wrap}.evaluation-counts button{border:0;background:none;font-size:12px;color:#5a7866;padding:0}.evaluation-counts strong{font-size:16px;margin-left:5px;color:#31523e}.attention-tabs{display:flex;border-bottom:1px solid #e1e8ed;margin-top:16px;gap:8px;flex-wrap:wrap}.attention-tabs button{border:0;border-bottom:2px solid transparent;background:none;padding:8px 12px;font-size:13px;color:#6e8075}.attention-tabs button.active{color:#2d6a4f;border-bottom-color:#2d6a4f;font-weight:600}.attention-tabs span{margin-left:7px;font-size:12px}.overview-attention-row{display:flex;gap:16px;align-items:start;padding:14px 0;border-bottom:1px solid #edf1ee}.overview-attention-row>div{flex:1;min-width:0}.overview-attention-row p{font-size:13px;color:#5f7267;margin:5px 0}.overview-attention-row small{font-size:11px;color:#829087}.overview-attention-row>.badge,.overview-attention-row>.text-link{white-space:nowrap}.attention-name{font-weight:600}.attention-paging{display:flex;justify-content:end;align-items:center;gap:12px;font-size:12px;margin-top:14px}.overview-modules,.overview-activities{overflow:auto}.table-card>.overview-heading{padding:16px 18px}.table-card h3{font-size:16px;color:#2d4b3c}.overview-modules table{min-width:700px}.overview-modules th:first-child{width:19%}.overview-modules th:nth-child(2){width:29%}.overview-modules th:nth-child(3){width:40%}.overview-modules td:last-child{white-space:nowrap}.module-metric{display:block;margin-bottom:7px;font-size:12px}.module-metric:last-child{margin-bottom:0}.module-metric b{margin-left:5px;color:#2d513b}.module-metric small{font-size:11px;margin-top:1px}.overview-activities table{min-width:690px}.overview-activities td:first-child{width:34%}.overview-methods{font-size:12px;color:#74867a;margin:18px 0}.overview-methods ul{padding-left:20px}.overview-methods li{margin:8px 0}.overview-shortcuts{display:flex;gap:18px;align-items:center;flex-wrap:wrap;margin:18px 0 4px}@media(max-width:1200px){.overview-top{grid-template-columns:1fr}.daily-chart{height:170px}.overview-heading{flex-wrap:wrap}.overview-filters label:first-child{min-width:240px}.overview-attention-row{flex-wrap:wrap}.overview-attention-row>div{flex-basis:65%}}@media(max-width:900px){.overview-filters label{flex:1}.overview-filters label:first-child{min-width:100%;}.overview-metrics{gap:10px}.overview-metrics .metric-card{padding:12px}.day-bar .bar-date{font-size:9px}}
</style>
